from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def cue(show,do,say,look,fallback):
    return f'SHOW: {show}\nDO: {do}\nSAY: {say}\nLOOK FOR: {look}\nFALLBACK: {fallback}\nPresenter notes stay on a private display. AEX rehearsal state belongs to Studio.'
